'use strict';
// Synthetic design state. No venue requests, credentials or production publication.
const dataTabs=[['connections','Подключения','Connections'],['markets','Рынки','Markets'],['collectors','Сбор данных','Collection'],['validator','Проверка данных','Validation'],['rating','Методика рейтинга','Rating methodology'],['results','Результаты','Results']];
const dataProfiles=[{id:'A',venue:'Polymarket',address:'0x'+'11'.repeat(20),days:45,actions:64,parts:[80,72,88,75],identity:'found',quality:'fresh'},{id:'B',venue:'Polymarket',address:'0x'+'22'.repeat(20),days:12,actions:8,parts:null,identity:'found',quality:'fresh'},{id:'C',venue:'Polymarket',address:'0x'+'33'.repeat(20),days:40,actions:22,parts:[60,64,68,65],identity:'found',quality:'fresh'},{id:'D',venue:'Limitless',address:'0x'+'44'.repeat(20),days:null,actions:null,parts:null,identity:'unknown',quality:'unknown'}];
const dataMarkets=[{id:'PM-DEMO-01',venue:'Polymarket',ru:'Учебный рынок A',en:'Synthetic market A',status:'open',time:'2026-10-23 12:00 UTC'},{id:'PM-DEMO-02',venue:'Polymarket',ru:'Учебный рынок B',en:'Synthetic market B',status:'resolved',time:'2026-10-23 11:40 UTC'},{id:'LL-DEMO-01',venue:'Limitless',ru:'Учебный рынок C',en:'Synthetic market C',status:'stale',time:'2026-10-23 10:20 UTC'}];
function newPlatforms(){return {tab:'connections',venue:'all',query:'',status:'all',market:null,profile:'A',source:'Polymarket',notice:null,error:null,outcome:'confirmed',technical:false,revision:1,command:null,history:[],collector:{Polymarket:{version:1,interval:5,days:90,paused:false},Limitless:{version:1,interval:5,days:90,paused:true}},collectorDraft:null,validator:{version:1,freshness:10},validatorDraft:null,rating:{version:1,weights:[30,25,25,20],days:30,actions:20},ratingDraft:null,comparison:null,publication:null,catalogVersion:1,versions:[{version:1,weights:[30,25,25,20],days:30,actions:20}],sourceState:{Polymarket:'ready',Limitless:'unconfigured'},diagnosis:null,formDrafts:{}};}
let platforms=newPlatforms();
function dataAccess(){const role=state.role,read=['ownerA','ownerB','lead','ops','audit'].includes(role)&&!!account?.logged;return {read,draft:read&&['ownerA','ownerB','lead'].includes(role),diagnose:read&&role!=='audit',apply:read&&!!actor().owner};}
const db=(ru,en,action,extra='',style='btn')=>`<button type="button" class="${style}" data-platform="${action}" ${extra}>${pl(ru,en)}</button>`;
const dlabel=(key)=>pl(...({collector:['Настройки сборщика','Collector settings'],pause:['Пауза сбора','Pause collection'],resume:['Возобновление сбора','Resume collection'],validator:['Правила проверки','Validation rules'],rating:['Методика рейтинга','Rating methodology'],ready:['Подключение доступно','Connection available'],unconfigured:['Не настроено','Not configured'],stale:['Устарело','Stale'],open:['Открыт','Open'],resolved:['Результат подтверждён','Resolved'],found:['Найден','Found'],unknown:['Не получен ответ','No confirmed response'],fresh:['Актуальные данные','Fresh data'],pending:['Выполняется','Pending'],confirmed:['Подтверждено','Confirmed'],failed:['Не выполнено','Failed'],conflict:['Версия изменилась','Version changed'],insufficient:['Недостаточно данных','Insufficient data'],draft:['Черновик','Draft'],paused:['Приостановлен','Paused'],running:['Сбор включён','Collection enabled']}[key]||[key,key]));
const dcommandLabel=k=>k==='unknown'?pl('Результат неизвестен','Outcome unknown'):dlabel(k);
function dataNav(){return dataAccess().read?db(icon('pulse')+t('data'),icon('pulse')+t('data'),'open','',state.route==='platforms'?'selected':''):'';}
function dataError(ru,en){platforms.error=[ru,en];return false;}
function dataRecords(){return dataMarkets.filter(m=>(platforms.venue==='all'||m.venue===platforms.venue)&&(platforms.status==='all'||m.status===platforms.status)&&[m.id,m.ru,m.en].join(' ').toLowerCase().includes(platforms.query.toLowerCase()));}
function dataEligibility(p,rule=platforms.rating){if(p.identity!=='found'||p.quality!=='fresh')return {score:null,reason:dlabel('unknown')};if(p.days<rule.days||p.actions<rule.actions)return {score:null,reason:dlabel('insufficient')};return {score:Math.round(p.parts.reduce((s,v,i)=>s+v*rule.weights[i]/100,0)),reason:pl('Подходит по учебному снимку','Eligible in synthetic snapshot')};}
const dtable=(heads,rows)=>`<div class="table-wrap" tabindex="0" role="region" aria-label="${pl('Таблица: прокрутка по горизонтали','Table: scroll horizontally')}"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const dfield=(id,ru,en,value,type='number',attrs='')=>`<div class="field"><label for="${id}">${pl(ru,en)}</label><input id="${id}" name="${id}" value="${escape(String(value))}" type="${type}" ${attrs}></div>`;
function dataFilters(markets=false){return `<form id="data-filter-form" class="finance-filters"><div class="field"><label for="data-venue">${t('venue')}</label><select id="data-venue" name="venue">${options([['all',pl('Все площадки','All venues')],['Polymarket','Polymarket'],['Limitless','Limitless']],platforms.venue)}</select></div>${markets?`<div class="field"><label for="data-search">${pl('Название или ID рынка','Market name or ID')}</label><input id="data-search" name="query" value="${escape(platforms.query)}"></div><div class="field"><label for="data-status">${t('status')}</label><select id="data-status" name="status">${options(['all','open','resolved','stale'].map(k=>[k,k==='all'?pl('Все состояния','All states'):dlabel(k)]),platforms.status)}</select></div>`:''}<button class="btn" type="submit">${pl('Применить','Apply')}</button>${db('Сбросить','Reset','reset')}</form>`;}
function dataPage(){if(!dataAccess().read)return heading(pl('Нет доступа к данным площадок','No venue-data access'));return heading(pl('Площадки и данные','Venues and data'),pl('Подключение, качество данных и рейтинг — отдельные результаты','Connection, data quality and rating are separate outcomes'))+`<div class="tabs" role="tablist">${dataTabs.map(([id,ru,en])=>db(ru,en,'tab',`data-tab="${id}" role="tab" aria-selected="${platforms.tab===id}"`,platforms.tab===id?'active':'')).join('')}</div><p class="muted">${pl('Учебный снимок 23 октября · API не подключены · параметры не являются реальными лимитами площадок.','Synthetic snapshot, 23 October · APIs are not connected · values are not actual venue limits.')}</p>${platforms.technical?`<p class="support-notice">${pl('Технический режим: новые продуктовые задания и публикация запрещены. Просмотр и сверка ранее принятой команды доступны.','Technical mode: new product jobs and publication are blocked. Viewing and reconciling an accepted command remain available.')}</p>`:''}${platforms.notice?`<p class="support-notice" role="status">${escape(pl(...platforms.notice))}</p>`:''}${platforms.error?`<p class="error" role="alert">${escape(pl(...platforms.error))}</p>`:''}<div class="data-content">${({connections:dataConnections,markets:dataMarketPage,collectors:dataCollectorPage,validator:dataValidatorPage,rating:dataRatingPage,results:dataResultsPage})[platforms.tab]()}</div>${dataScenario()}`;}
function dataConnections(){return dataFilters()+dtable([t('venue'),pl('Подключение','Connection'),pl('Данные для рейтинга','Rating data'),pl('Следующий шаг','Next step')],['Polymarket','Limitless'].filter(v=>platforms.venue==='all'||v===platforms.venue).map(v=>`<tr><td>${v}<small>${v==='Polymarket'?'SRC-DEMO-PM':'SRC-DEMO-LL'} · Paper Alpha</small></td><td>${dlabel(platforms.sourceState[v])}</td><td>${v==='Polymarket'?pl('Подходят: ','Eligible: ')+dataProfiles.filter(p=>p.venue===v&&dataEligibility(p,platforms.versions.find(r=>r.version===platforms.catalogVersion)).score!==null).map(p=>p.id).join(', ')+pl('; остальные — см. причины','; see reasons for other profiles'):pl('Не получены; рейтинг отсутствует','Not received; no rating')}</td><td><div class="actions">${db('Открыть сборщик','Open collector','source',`data-source="${v}"`)}${dataAccess().diagnose?db('Диагностика','Diagnose','diagnose',`data-source="${v}"`):''}</div></td></tr>`))+`<section class="panel"><h2>${pl('Свежесть и охват','Freshness and coverage')}</h2><p>${pl('Polymarket: 3 профиля с проверенными учебными данными. Limitless: ответ не получен, охват неизвестен. Это не ноль профилей.','Polymarket: 3 profiles with validated synthetic data. Limitless: no response, coverage unknown. This does not mean zero profiles.')}</p>${platforms.diagnosis?`<p role="status">${escape(pl(...platforms.diagnosis))}</p>`:''}${db('Открыть результаты проверки','View validation results','tab','data-tab="results"')}</section>`;}
function dataMarketPage(){const m=dataMarkets.find(x=>x.id===platforms.market);if(m)return heading(pl(m.ru,m.en),m.id,db('К рынкам','Back to markets','market-back'))+`<section class="panel"><dl class="account-facts"><div><dt>${t('venue')}</dt><dd>${m.venue}</dd></div><div><dt>${t('status')}</dt><dd>${dlabel(m.status)}</dd></div><div><dt>${pl('Обновлено','Updated')}</dt><dd>${m.time}</dd></div><div><dt>${pl('Правила и результат','Rules and resolution')}</dt><dd>${pl('Точные условия источника не подключены. Учебный статус не разрешает торговлю.','Source conditions are not connected. Synthetic status does not authorize trading.')}</dd></div></dl>${db('Открыть источник данных','Open data source','source',`data-source="${m.venue}"`)}</section>`;const rows=dataRecords();return dataFilters(true)+(rows.length?dtable([pl('Рынок','Market'),t('venue'),t('status'),pl('Обновлено','Updated')],rows.map(m=>`<tr><td>${db(pl(m.ru,m.en),pl(m.ru,m.en),'market',`data-id="${m.id}"`,'user-link')}<small>${m.id}</small></td><td>${m.venue}</td><td>${dlabel(m.status)}</td><td>${m.time}</td></tr>`)):`<section class="panel"><h2>${pl('Рынки не найдены','No markets found')}</h2>${db('Сбросить фильтры','Clear filters','reset')}</section>`);}
function dataCommandView(){const c=platforms.command;if(!c)return '';return `<section class="panel"><h3>${pl('Команда','Command')} ${c.id}</h3><p>${escape(c.source)} · ${dlabel(c.kind)} · ${dcommandLabel(c.status)}</p><p>${pl('Принятие команды не означает применение. Неизвестный результат проверяется по тому же ID без повторной отправки.','Accepted does not mean applied. An unknown result is checked by the same ID without resending.')}</p>${['pending','unknown'].includes(c.status)&&dataAccess().diagnose?db('Проверить результат команды','Check command result','reconcile'):''}</section>`;}
function dataCollectorPage(){const c=platforms.collector[platforms.source],d=platforms.collectorDraft?.source===platforms.source?platforms.collectorDraft:c;const raw=platforms.formDrafts['collector:'+platforms.source]||d;return `<div class="field"><label for="data-source">${t('venue')}</label><select id="data-source" data-platform-source>${options([['Polymarket','Polymarket'],['Limitless','Limitless']],platforms.source)}</select></div><section class="panel"><h2>${pl('Каталог и публичная история','Catalog and public history')} · ${platforms.source}</h2><p>P-${c.version} · ${dlabel(c.paused?'paused':'running')} · ${c.interval} ${pl('минут','minutes')} / ${c.days} ${pl('дней','days')}</p><p class="muted">${pl('Пауза сохраняет историю и контрольную точку. Свежесть рейтинга ухудшается; торговые сессии этой командой не останавливаются. Интервал не управляет торговым потоком.','Pausing preserves history and checkpoints. Rating freshness degrades; this command does not stop trading sessions. The interval does not control the trading pipeline.')}</p>${dataAccess().draft?`<form id="data-collector-form"><div class="form-grid">${dfield('interval','Интервал учебного сбора, минуты','Synthetic collection interval, minutes',raw.interval,'number','min="1" max="60" required')}${dfield('days','Окно учебной истории, дни','Synthetic history window, days',raw.days,'number','min="1" max="365" required')}</div><button class="btn" type="submit">${pl('Сохранить черновик','Save draft')}</button></form>`:''}${platforms.collectorDraft?.source===platforms.source?`<p>${pl('Черновик','Draft')}: ${platforms.collectorDraft.interval} / ${platforms.collectorDraft.days}. ${pl('Не применён','Not applied')}</p>${dataAccess().apply?db('Проверить и применить черновик','Validate and apply draft','apply-collector'):''}`:''}<div class="actions">${dataAccess().apply?db(c.paused?'Возобновить сбор':'Приостановить сбор',c.paused?'Resume collection':'Pause collection',c.paused?'resume':'pause'):''}</div></section>${dataCommandView()}${dataHistory()}`;}
function dataValidatorPage(){const p=dataProfiles.find(x=>x.id===platforms.profile),r=dataEligibility(p);return `<section class="panel"><h2>${pl('Проверить профиль источника','Inspect source profile')}</h2><div class="field"><label for="data-profile">${pl('Учебный профиль','Synthetic profile')}</label><select id="data-profile" data-platform-profile>${options(dataProfiles.map(p=>[p.id,p.id+' · '+p.venue]),platforms.profile)}</select></div><p class="full-address">${p.address}</p><dl class="account-facts"><div><dt>${pl('Идентичность','Identity')}</dt><dd>${dlabel(p.identity)}</dd></div><div><dt>${pl('Пригодность данных','Data quality')}</dt><dd>${dlabel(p.quality)}</dd></div><div><dt>${pl('Допуск по методике','Eligibility under methodology')} R-${platforms.rating.version}</dt><dd>${r.reason}</dd></div></dl><p>${pl('Недоступность источника не означает, что адрес не существует. Отсутствие рейтинга само по себе не запрещает ручной поиск.','Source unavailability does not mean an address does not exist. No rating does not by itself prevent manual search.')}</p>${dataAccess().diagnose?db('Повторить чтение источника','Read source again','validate'):''}</section><section class="panel"><h2>${pl('Правила проверки','Validation rules')} · V-${platforms.validator.version}</h2><p>${pl('Идентичность, обязательные поля, дубликаты, происхождение и необъяснённые расхождения проверяются всегда. Их нельзя отключить.','Identity, required fields, duplicates, provenance and unexplained discrepancies are always checked and cannot be disabled.')}</p>${dataAccess().draft?`<form id="data-validator-form">${dfield('freshness','Актуальность рейтинговых данных, минуты · учебное значение','Rating-data freshness, minutes · synthetic value',platforms.formDrafts.validator?.freshness??platforms.validatorDraft?.freshness??platforms.validator.freshness,'number','min="1" max="60" required')}<button class="btn" type="submit">${pl('Сохранить черновик','Save draft')}</button></form>`:''}${platforms.validatorDraft?`<p>${pl('Черновик','Draft')}: ${platforms.validatorDraft.freshness} ${pl('минут','minutes')}</p>${dataAccess().apply?db('Применить проверенную версию','Apply validated version','apply-validator'):''}`:''}</section>${dataCommandView()}`;}
function dataRatingPage(){const d=platforms.ratingDraft||platforms.rating,raw=platforms.formDrafts.rating||{};return `<section class="panel"><h2>${pl('Качество копирования','Copying quality')} · R-${platforms.rating.version}</h2><p>${pl('Индекс 0–100, не вероятность прибыли. Количество копировщиков не влияет. Каталог использует полный снимок DS-DEMO-01 / R-','Index 0–100, not profit probability. Copier count has no effect. Catalog uses complete snapshot DS-DEMO-01 / R-')}${platforms.catalogVersion}.</p><p>${pl('Публикация методики и готовность нового каталога — разные этапы. До подтверждения полного расчёта клиентский каталог остаётся на прежней версии.','Publishing a methodology and preparing a new catalog are separate stages. The old catalog remains active until a complete calculation is confirmed.')}</p>${dataAccess().draft?`<form id="data-rating-form"><div class="form-grid">${[['Данные','Data'],['Просадка','Drawdown'],['Копируемость','Copyability'],['Стабильность после расходов','Stability after costs']].map(([ru,en],i)=>dfield('weight'+i,ru+', %',en+', %',raw['weight'+i]??d.weights[i],'number','min="0" max="100" required')).join('')}${dfield('rating-days','Минимум дней','Minimum days',raw['rating-days']??d.days,'number','min="30" required')}${dfield('rating-actions','Минимум подходящих действий','Minimum eligible actions',raw['rating-actions']??d.actions,'number','min="20" required')}</div><button class="btn" type="submit">${pl('Сохранить черновик','Save draft')}</button></form>`:''}<div class="actions">${platforms.ratingDraft&&dataAccess().draft?db('Сравнить на одном снимке','Compare on one snapshot','compare'):''}${platforms.comparison&&dataAccess().apply?db('Опубликовать проверенную методику','Publish validated methodology','publish-rating'):''}</div></section>${platforms.comparison?`<section class="panel"><h2>${pl('Сравнение на DS-DEMO-01','Comparison on DS-DEMO-01')}</h2>${dtable([pl('Профиль','Profile'),pl('Текущая методика','Current methodology'),pl('Черновик','Draft')],dataProfiles.map(p=>{const a=dataEligibility(p),b=dataEligibility(p,platforms.ratingDraft);return `<tr><td>${p.id} · ${p.venue}</td><td>${a.score??a.reason}</td><td>${b.score??b.reason}</td></tr>`;}))}</section>`:''}${platforms.publication?`<section class="panel"><h2>${pl('Новый расчёт','New calculation')} · R-${platforms.publication.version}</h2><p>${dcommandLabel(platforms.publication.status)} · ${pl('Попытка','Attempt')} ${platforms.publication.attempt||1}</p>${['failed','conflict'].includes(platforms.publication.status)&&dataAccess().apply?db('Запустить новый расчёт','Start a new calculation','catalog-retry'):''}${['pending','unknown'].includes(platforms.publication.status)&&dataAccess().apply?db('Проверить готовность полного снимка','Check complete snapshot','catalog-check'):''}</section>`:''}<section class="panel"><h2>${pl('История методик','Methodology history')}</h2>${platforms.versions.map(v=>`<p>R-${v.version} · ${v.weights.join('/')} · ${v.days} ${pl('дней','days')} / ${v.actions} ${pl('действий','actions')} ${dataAccess().apply&&v.version!==platforms.rating.version?db('Восстановить в новый черновик','Restore as a new draft','restore',`data-version="${v.version}"`):''}</p>`).join('')}</section>${dataCommandView()}`;}
function dataResultsPage(){const rule=platforms.versions.find(v=>v.version===platforms.catalogVersion)||platforms.rating;return dataFilters()+`<p>DS-DEMO-01 / R-${rule.version} · ${pl('Подтверждённый учебный каталог. Исходные события не редактируются.','Confirmed synthetic catalog. Source events are read-only.')}</p>`+dtable([pl('Профиль / полный адрес','Profile / full address'),pl('Идентичность','Identity'),pl('Данные','Data'),pl('Качество копирования','Copying quality')],dataProfiles.filter(p=>platforms.venue==='all'||p.venue===platforms.venue).map(p=>{const r=dataEligibility(p,rule);return `<tr><td>${db(p.id+' · '+p.venue,p.id+' · '+p.venue,'profile',`data-id="${p.id}"`,'user-link')}<small class="full-address">${p.address}</small></td><td>${dlabel(p.identity)}</td><td>${p.days===null?pl('Не получены','Not received'):p.days+pl(' дней / ',' days / ')+p.actions+pl(' действий',' actions')}</td><td>${r.score===null?r.reason:r.score+' / 100'}</td></tr>`;}));}
function dataHistory(){return `<section class="panel"><h3>${pl('История команд','Command history')}</h3>${platforms.history.length?platforms.history.map(h=>`<p>${h.id} · ${h.source} · ${h.actor} · ${dcommandLabel(h.status)}</p>`).join(''):`<p>${pl('В этом сеансе команд ещё нет','No commands in this session')}</p>`}</section>`;}
function dataScenario(){return `<details class="account-test"><summary>${pl('Учебные состояния — не рабочие настройки','Synthetic outcomes — not operational settings')}</summary><div class="field"><label for="data-outcome">${pl('Следующий ответ','Next response')}</label><select id="data-outcome" data-platform-outcome>${options(['confirmed','pending','unknown','failed','conflict'].map(v=>[v,dcommandLabel(v)]),platforms.outcome)}</select></div><label><input type="checkbox" data-platform-technical ${platforms.technical?'checked':''}> ${pl('Технический режим','Technical mode')}</label></details>`;}
function dataSubmitCommand(kind,payload){if(!dataAccess().apply)return dataError('Применение доступно владельцу','Only an owner can apply');if(platforms.technical)return dataError('Технический режим запрещает эту команду','Technical mode blocks this command');if(platforms.command&&['pending','unknown'].includes(platforms.command.status))return dataError('Сначала проверьте ранее принятую команду','Check the accepted command first');if(payload.base!==platforms.revision)return dataError('Версия изменилась. Обновите черновик и сравнение','Version changed. Refresh the draft and comparison');const c={id:'CMD-DEMO-'+(platforms.history.length+1),kind,source:payload.source||platforms.source,actor:actor().id,payload:structuredClone(payload),status:'pending',applied:false};platforms.command=c;platforms.history.push(c);dataResolveCommand();return true;}
function dataResolveCommand(){const c=platforms.command;if(!c||!['pending','unknown'].includes(c.status))return false;c.status=platforms.outcome;if(['pending','unknown'].includes(c.status))return true;if(c.status==='conflict'){platforms.revision++;return true;}if(c.status!=='confirmed')return true;if(c.payload.base!==platforms.revision){c.status='conflict';return false;}if(c.applied)return false;const p=c.payload;if(c.kind==='collector'){Object.assign(platforms.collector[c.source],{interval:p.interval,days:p.days,version:platforms.collector[c.source].version+1});if(JSON.stringify(platforms.collectorDraft)===JSON.stringify(p))platforms.collectorDraft=null;}if(c.kind==='pause'||c.kind==='resume')platforms.collector[c.source].paused=c.kind==='pause';if(c.kind==='validator'){platforms.validator={version:platforms.validator.version+1,freshness:p.freshness};if(JSON.stringify(platforms.validatorDraft)===JSON.stringify(p))platforms.validatorDraft=null;}if(c.kind==='rating'){const next={version:platforms.rating.version+1,weights:p.weights,days:p.days,actions:p.actions};platforms.rating=next;platforms.versions.push(structuredClone(next));platforms.publication={version:next.version,status:'pending',attempt:1};if(JSON.stringify(platforms.ratingDraft)===JSON.stringify(p)){platforms.ratingDraft=null;platforms.comparison=null;}}c.applied=true;platforms.revision++;return true;}
function dataSaveDraft(kind,values){if(!dataAccess().draft)return false;platforms.error=null;if(kind==='collector'){const interval=Number(values.interval),days=Number(values.days);if(!Number.isInteger(interval)||interval<1||interval>60||!Number.isInteger(days)||days<1||days>365)return dataError('Проверьте учебный интервал 1–60 и историю 1–365 целых дней','Use an integer demo interval 1–60 and history 1–365 days');platforms.collectorDraft={source:platforms.source,interval,days,base:platforms.revision};}else if(kind==='validator'){const freshness=Number(values.freshness);if(!Number.isInteger(freshness)||freshness<1||freshness>60)return dataError('Введите целое учебное значение 1–60','Enter an integer demo value 1–60');platforms.validatorDraft={freshness,base:platforms.revision};}else{const weights=[0,1,2,3].map(i=>Number(values['weight'+i])),days=Number(values['rating-days']),actions=Number(values['rating-actions']);if(weights.some(x=>!Number.isFinite(x)||x<0||x>100)||Math.abs(weights.reduce((a,b)=>a+b,0)-100)>.000001||!Number.isInteger(days)||days<30||!Number.isInteger(actions)||actions<20)return dataError('Веса должны составлять 100%; минимум 30 дней и 20 действий','Weights must total 100%; minimum 30 days and 20 actions');platforms.ratingDraft={weights,days,actions,base:platforms.revision};platforms.comparison=null;}platforms.notice=['Черновик сохранён. Действующие настройки не изменены.','Draft saved. Active settings have not changed.'];return true;}
function dataAction(action,el={dataset:{}}){if(!dataAccess().read)return false;const ds=el.dataset||{};platforms.error=null;platforms.notice=null;if(action==='open')navigate('platforms');else if(action==='tab'){platforms.tab=ds.tab;platforms.market=null;navigate('platforms');}else if(action==='reset'){platforms.venue='all';platforms.query='';platforms.status='all';}else if(action==='market')platforms.market=ds.id;else if(action==='market-back')platforms.market=null;else if(action==='source'){platforms.source=ds.source;platforms.tab='collectors';}else if(action==='profile'){platforms.profile=ds.id;platforms.tab='validator';}else if(action==='diagnose'||action==='validate'){if(!dataAccess().diagnose)return false;const source=ds.source||dataProfiles.find(p=>p.id===platforms.profile)?.venue;platforms.diagnosis=source==='Limitless'?['Limitless: нет настроенного источника. Данные не получены; адрес не объявляется несуществующим.','Limitless: no configured source. Data was not received; this does not mean the address does not exist.']:['Polymarket: учебное чтение завершено. Снимок DS-DEMO-01 не изменён.','Polymarket: synthetic read completed. Snapshot DS-DEMO-01 is unchanged.'];platforms.notice=platforms.diagnosis;}else if(action==='apply-collector'){const d=platforms.collectorDraft;if(!d||d.source!==platforms.source)return false;return dataSubmitCommand('collector',d);}else if(action==='pause'||action==='resume'){if(action==='resume'&&platforms.sourceState[platforms.source]!=='ready')return dataError('Источник не настроен. Возобновление недоступно','Source is not configured. Resume is unavailable');return dataSubmitCommand(action,{source:platforms.source,base:platforms.revision});}else if(action==='apply-validator'){if(!platforms.validatorDraft)return false;return dataSubmitCommand('validator',platforms.validatorDraft);}else if(action==='reconcile'){if(!dataAccess().diagnose)return false;return dataResolveCommand();}else if(action==='compare'){if(!dataAccess().draft||!platforms.ratingDraft)return false;platforms.comparison=JSON.stringify(platforms.ratingDraft);}else if(action==='publish-rating'){const d=platforms.ratingDraft;if(!d||platforms.comparison!==JSON.stringify(d))return dataError('Сначала сравните текущий черновик','Compare the current draft first');if(platforms.publication&&['pending','unknown'].includes(platforms.publication.status))return dataError('Дождитесь результата предыдущего расчёта','Wait for the previous calculation result');return dataSubmitCommand('rating',d);}else if(action==='catalog-check'){if(!dataAccess().apply||!platforms.publication||!['pending','unknown'].includes(platforms.publication.status))return false;if(platforms.technical)return dataError('Публикация каталога запрещена техническим режимом','Catalog publication is blocked by technical mode');platforms.publication.status=platforms.outcome;if(platforms.outcome==='confirmed')platforms.catalogVersion=platforms.publication.version;}else if(action==='catalog-retry'){if(!dataAccess().apply||platforms.technical||!platforms.publication||!['failed','conflict'].includes(platforms.publication.status)||platforms.publication.version!==platforms.rating.version)return false;platforms.publication.status='pending';platforms.publication.attempt=(platforms.publication.attempt||1)+1;}else if(action==='restore'){if(!dataAccess().apply)return false;const v=platforms.versions.find(v=>v.version===Number(ds.version));if(!v)return false;platforms.ratingDraft={weights:[...v.weights],days:v.days,actions:v.actions,base:platforms.revision};delete platforms.formDrafts.rating;platforms.comparison=null;platforms.notice=['Создан новый черновик. История и прошлые сделки сохраняются.','New draft created. History and past trades remain unchanged.'];}else return false;return true;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-platform]');if(!el||el.disabled)return;dataAction(el.dataset.platform,el);render();});
document.addEventListener('change',e=>{const el=e.target;if(el.hasAttribute('data-platform-source'))platforms.source=el.value;else if(el.hasAttribute('data-platform-profile'))platforms.profile=el.value;else if(el.hasAttribute('data-platform-outcome'))platforms.outcome=el.value;else if(el.hasAttribute('data-platform-technical'))platforms.technical=el.checked;else return;render();});
document.addEventListener('submit',e=>{const id=e.target.id;if(!id.startsWith('data-'))return;e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(id==='data-filter-form'){platforms.venue=values.venue;platforms.query=values.query||'';platforms.status=values.status||'all';}else dataSaveDraft(id==='data-collector-form'?'collector':id==='data-validator-form'?'validator':'rating',values);render();});

document.addEventListener('input',e=>{const form=e.target.closest('form');if(!form)return;const key=form.id==='data-collector-form'?'collector:'+platforms.source:form.id==='data-validator-form'?'validator':form.id==='data-rating-form'?'rating':null;if(key)platforms.formDrafts[key]=Object.fromEntries(new FormData(form));});
